mapper.select:
SELECT EXISTS(
  SELECT 1 FROM chengke_crm.department_closure
  WHERE tenant_id=#{tenantId} AND ancestor_id=#{ancestorId}
    AND descendant_id=#{descendantId} AND distance>0
)

SELECT EXISTS(
  SELECT 1 FROM chengke_crm.department_closure c
  JOIN chengke_crm.department a ON a.tenant_id=c.tenant_id AND a.id=c.ancestor_id
  WHERE c.tenant_id=#{tenantId} AND c.descendant_id=#{departmentId}
    AND c.distance>0 AND a.deleted_at IS NULL AND a.status='disabled'
)
